            except Exception:
                return default
        return default

    def clamp_step(a, b):
        d = b - a
        return 0 if d == 0 else (1 if d > 0 else -1)

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def step_toward(a, b):
        return [clamp_step(a[0], b[0]), clamp_step(a[1], b[1])]

    def step_away(a, b):
        return [clamp_step(b[0], a[0]), clamp_step(b[1], a[1])]

    def best_by_distance(origin, items, prefer_far=False):
        best_item = None
        best_score = None
        for item in items:
            p = pos(item, None)
