        return step_toward((sx, sy), target)

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("neutral_cells") or []
        target = best_by_distance((sx, sy), targets, prefer_far=False)
        if target is not None:
            return step_toward((sx, sy), target)
        if grid_w > 0 and grid_h > 0:
            center = (grid_w // 2, grid_h // 2)
            return step_toward((sx, sy), center)
        return step_toward((sx, sy), (ox, oy))

